values ('road-to-hyrox', '{"ms":{"title":"Menuju HYROX","summary":"DRAF — perlu semakan coach. Sepuluh minggu larian, interval 1KM dan kekuatan untuk 8 × 1KM dan stesen HYROX.","who":"Untuk yang boleh lari 30 minit berterusan dan mahu tamat HYROX pertama."},"en":{"title":"Road to HYROX","summary":"DRAFT — needs coach review. Ten weeks of running, 1KM intervals and strength for the 8 × 1KM and HYROX stations.","who":"For runners who can run 30 minutes continuously and want to finish a first HYROX."}}'::jsonb, 'hyrox', 'intermediate', 10, 4, 8000, 'free', 'draft', 60)
