select id, 1, 1, 'easy', '{"ms":{"title":"Larian Santai 30 minit","objective":"Bina daya tahan aerobik. Larian berterusan tanpa berhenti.","warmup":"Jalan laju 5 minit, kemudian 30 saat setiap satu: angkat lutut, tendang punggung, ayun kaki ke depan dan ke sisi.","main":"DRAF — perlu semakan coach. Lari berterusan 30 minit pada pace perbualan.","cooldown":"Jalan perlahan 5 minit. Regangan betis, paha depan dan belakang, 30 saat setiap sisi.","coach":"DRAF — perlu semakan coach. Pace perbualan: anda patut boleh bercakap dalam ayat penuh. Kalau tercungap, perlahankan atau jalan sekejap."},"en":{"title":"Easy Run 30 min","objective":"Build aerobic endurance. Continuous running without stopping.","warmup":"Brisk walk 5 minutes, then 30 seconds each: high knees, butt kicks, front and side leg swings.","main":"DRAFT — needs coach review. Run continuously for 30 minutes at conversational pace.","cooldown":"Easy walk 5 minutes. Stretch calves, quads and hamstrings, 30 seconds each side.","coach":"DRAFT — needs coach review. Conversational pace: you should be able to talk in full sentences. If you are gasping, slow down or walk briefly."}}'::jsonb, 40, null, 'easy', 3, 5, null, '[{"kind":"run","sec":1800}]'::jsonb
  from public.run_programs where slug = 'road-to-hyrox'
