select id, 1, 2, 'strength', '{"ms":{"title":"Kekuatan: Kuasa & Pecut","objective":"Kaki dan core yang kuat untuk larian dan stesen.","warmup":"Termasuk dalam sesi video.","main":"DRAF — perlu semakan coach. Ikut sesi video HITFAT “Kuasa & Pecut” dalam app (18 minit).","cooldown":"Jalan perlahan 3 minit dan regangan ringan.","coach":"DRAF — perlu semakan coach."},"en":{"title":"Strength: Power & Speed","objective":"Strong legs and core for the runs and the stations.","warmup":"Included in the video session.","main":"DRAFT — needs coach review. Follow the HITFAT video session “Power & Speed” in the app (18 minutes).","cooldown":"Walk 3 minutes and stretch lightly.","coach":"DRAFT — needs coach review."}}'::jsonb, 18, null, 'moderate', 5, 7, null, '[{"kind":"strength","workout":"kuasa-pecut"}]'::jsonb
