select id, 6, 4, 'interval', '{"ms":{"title":"Lari + Stesen 5 × 1KM","objective":"Biasakan berlari dengan kaki yang sudah penat, seperti dalam HYROX.","warmup":"Jalan laju 5 minit, kemudian 30 saat setiap satu: angkat lutut, tendang punggung, ayun kaki ke depan dan ke sisi. Tambah 10 minit lari santai.","main":"DRAF — perlu semakan coach. 5 kali: lari 1KM pada pace perlumbaan, terus buat 1 stesen tanpa rehat (bergilir: 20 lunge berjalan, 15 burpee, 30 saat wall sit, 20 squat jump).","cooldown":"Jalan perlahan 5 minit. Regangan betis, paha depan dan belakang, 30 saat setiap sisi.","coach":"DRAF — perlu semakan coach. Peralihan dari stesen ke larian ialah kemahiran: mula 200 meter pertama sedikit perlahan."},"en":{"title":"Run + Station 5 × 1KM","objective":"Get used to running on tired legs, as in HYROX.","warmup":"Brisk walk 5 minutes, then 30 seconds each: high knees, butt kicks, front and side leg swings. Add 10 minutes of easy running.","main":"DRAFT — needs coach review. 5 times: run 1KM at race pace, then go straight into 1 station without rest (rotate: 20 walking lunges, 15 burpees, 30 s wall sit, 20 squat jumps).","cooldown":"Easy walk 5 minutes. Stretch calves, quads and hamstrings, 30 seconds each side.","coach":"DRAFT — needs coach review. Going from a station back to running is a skill: take the first 200 m a little slower."}}'::jsonb, 65, 5000, 'hard', 6, 8, 'station', null
