select id, 9, 3, 'interval', '{"ms":{"title":"Interval 7 × 1KM","objective":"Tingkatkan kelajuan dan kecekapan larian pada pace 5KM.","warmup":"Jalan laju 5 minit, kemudian 30 saat setiap satu: angkat lutut, tendang punggung, ayun kaki ke depan dan ke sisi. Tambah 10 minit lari santai.","main":"DRAF — perlu semakan coach. 7 kali 1000 meter pada pace yang anda boleh kekalkan untuk 5KM (usaha 7–8/10). Rehat 2 minit jog atau jalan di antara.","cooldown":"10 minit lari sangat santai, kemudian regangan.","coach":"DRAF — perlu semakan coach. Set pertama patut rasa terkawal. Kalau set terakhir jauh lebih perlahan, set awal anda terlalu laju."},"en":{"title":"Intervals 7 × 1KM","objective":"Improve speed and running economy at 5KM pace.","warmup":"Brisk walk 5 minutes, then 30 seconds each: high knees, butt kicks, front and side leg swings. Add 10 minutes of easy running.","main":"DRAFT — needs coach review. 7 × 1000 m at the pace you could hold for a 5KM (effort 7–8/10). Rest 2 min jog or walk between.","cooldown":"10 minutes very easy running, then stretch.","coach":"DRAFT — needs coach review. The first rep should feel controlled. If your last rep is much slower, you started too fast."}}'::jsonb, 73, null, 'hard', 7, 8, '2 jog/walk', null
